-- GENERATED by `wfj generate` from data/gossip/gossip-0b.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["0b0d0f32c1670c68"] = { "Non mostrate loro pietà!", "." },
  ["0b1bb72e1bd0d4d1"] = { "Scappate!", "." },
  ["0b1eebc6273d9449"] = { "Salve, <viaggiatore/viaggiatrice>. Non sono in molti a trovarmi fin quaggiù.\n\nMi chiamo Rivern, e addestro le fiere glaciali di ⟦Winterspring=Fontefredda⟧ perché diventino cavalcature.\n\nQuesti felini sono i più selvaggi e difficili da domare tra tutte le fiere. Solo i più fidati e osannati possono tentare di cavalcarne una.\n\nNon venderò una cavalcatura simile a chiunque; no, dovrai lavorare per ottenerla e guadagnarti l'approvazione non solo mia, ma anche delle fiere stesse.", "." },
  ["0b2398aa942bb30d"] = { "Maledetti coboldi. Non riesco a combinare niente con loro che corrono avanti e indietro e mi stanno tra i piedi. Be', non ho niente di meglio da fare: vuoi imparare qualche tecnica di estrazione? O forse ti servono solo attrezzi nuovi?", "." },
  ["0b25f7899e783f2b"] = { "Come vuoi, vuol dire che non hai poi tanta fame. La prossima volta il cibo te lo prepari tu!", "." },
  ["0b2e1cdc63445569"] = { "Abbiamo fallito, {name}!!", "." },
  ["0b31490beb45d076"] = { "Di' a Lexlort che se vuole le informazioni, deve solo pagare! Purtroppo questo significa che non può uccidermi, se vuole le informazioni, visto che i piani di battaglia li ho bruciati...", "." },
  ["0b34c7f184ff05f3"] = { "Finalmente! Non vedo l'ora di dormire un po' stanotte.", "." },
  ["0b35c012e7eec4d2"] = { "Mmm, chissà cosa c'è da questa parte?", "." },
  ["0b3722a8545f17d4"] = { "L'unica anomalia di sintesi dei Terrigeni è la tendenza alla destabilizzazione della matrice quando vengono impiegati in ambienti ad alto stress.\n\nAddendum: la scultura della terra profonda si adattava naturalmente al nuovo progetto di matrice, e quindi non ha mai soddisfatto i requisiti per riprodurre un ambiente ad alto stress.\n\nLa destabilizzazione fu scoperta solo quando il ciclo di servizio primario dei Terrigeni per i Creatori era ormai ben avviato. I Creatori iniziarono a lavorare a una modifica post-sintesi, anziché al richiamo e a una nuova sintesi.", "." },
  ["0b39a5af29d18de5"] = { "Parla con il guardiamorte Billmuth a Tyr's Watch.", "." },
  ["0b3ae28779961b66"] = { "Signore?", "." },
  ["0b3ee529d17058f2"] = { "Malorne riesce in qualche modo a raccogliere le erbe più delicate senza danneggiarle. È senz'altro lui quello da cui dovresti imparare. Vive appena a est della locanda di Dolanaar.", "." },
  ["0b4209381ffa6527"] = { "La lezione è cominciata!", "." },
  ["0b4747808eeb44b7"] = { "Questa sana pianta di sferzarapa è l'esatto opposto della malsana corruzione che domina ⟦Felwood=Vilbosco⟧. Radici tenere e sane producono deliziosi tuberi che giacciono a terra accanto alla pianta.", "." },
  ["0b4946b7fa2c670b"] = { "L'⟦Horde=Orda⟧ ha conquistato la segheria!", "." },
  ["0b4b8ddbff75ed76"] = { "Benvenut<o/a>, <sacerdote/sacerdotessa>. L'⟦The Eye of Zuldazar=Occhio di Zuldazar⟧ pulsa di energia. Sei pront<o/a> per il passo successivo. Dammi il talismano e compirò l'infusione.", "." },
  ["0b4d26d2cac232db"] = { "Ah... gli eroi. Siete tenaci, eh? Il vostro alleato qui ha provato a misurare il suo potere con il mio, e ne ha pagato il prezzo. Ora servirà me... massacrandovi.", "." },
  ["0b54d49875bf9ada"] = { "Salve, Zando'zan, vorrei imparare lo scasso.", "." },
  ["0b567a767e6ddd52"] = { "%s è molto più vulnerabile ai tuoi attacchi. Felcurse sta facendo effetto!", "." },
  ["0b62e4d2569afbd9"] = { "Mi dispiace. Al momento non posso aiutarti.", "." },
  ["0b658b8e153ce9a2"] = { "Non darti pena, amore mio. Mi hai liberato dalla schiavitù, e per questo ti amo ancora di più.", "." },
  ["0b6e7bec570496bd"] = { "Cosa ha detto Gryphe a capo?? Gryphe non mentiva! Eccola lì, cerca di rubare i piani di battaglia!", "." },
  ["0b71157ddc9fcc66"] = { "Seguaci, servitori, soldati del freddo buio! Obbedite al richiamo di Kel'Thuzad!", "." },
  ["0b747af02ade31ab"] = { "Dov'è l'anziano Spira Dura?", "." },
  ["0b7a3a3465548d4f"] = { "Forse sono stato troppo precipitoso nel giudicarti, {class}. Pare che la tua fede cieca in questa Luce abbia un qualche valore, dopotutto.\n\nDammi il tuo marchio e ne amplificherò il potere.", "." },
  ["0b7c867f8e765823"] = { "⟦Chaw Stronghide=Chaw Pelle Forte⟧ risiede nella grande tenda all'angolo nord-ovest del villaggio. Per ora ti insegnerà ciò che devi sapere sulla Conciatura.", "." },
  ["0b7ef27c8c743d18"] = { "Uff.", "." },
  ["0b8098cdf6933d19"] = { "Ecco fatto: ora puoi fabbricare una ⟦Lodestone=Magnetite⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", "." },
  ["0b834f3eaa746117"] = { "Come hai richiesto, il caporale Splithoof è arrivato, {name}.", "." },
  ["0b84e029089ae3cc"] = { "Percepisco l'OMBRA nei vostri cuori. Non c'è pace per i malvagi!", "." },
  ["0b850e7b78b68681"] = { "Hai visto cose strane nel deserto, di recente?", "." },
  ["0b8a48e159762bc6"] = { "Che freddo... e che fame.\n\nPovero amico mio, spero che tu abbia trovato la pace. Non sopporto il pensiero di ciò che potrebbero averti fatto.\n\nTu! Tu, lì! Ti prego, devi aiutarmi a fuggire. Uno di loro ha una chiave, riesci a trovarla? So che ce l'hanno. Se la prendi, puoi aiutarmi a uscire di qui. Trey sarà già morto, ma c'è ancora tempo! Ti prego, puoi aiutarmi?", "." },
  ["0b8cba841abf8212"] = { "Cerco addestramento nelle vie del Cacciatore.", "." },
  ["0b961d60e92041a3"] = { "Sai, potrei trafiggere un orco o fare a fette un troll. Potrei perfino incidere le mie iniziali sul fianco di un ogre, ma proprio non sopporto di scuoiare un animale. Vai a capire, eh.\n\nBe', se hai lo stomaco per farlo, vai da Maris Granger al Protective Hide, nella Città Vecchia.", "." },
  ["0b97c108d95f40c2"] = { "Diviso in due per formare l'uno. Le lame gemelle sono legate a ⟦Zul'Farrak=Zul'farrak⟧.\n\nSul'thraze rinasce quando i gemelli sono ritrovati.", "." },
  ["0ba03211488afd5b"] = { "Nessuno ruberà i segreti dei Creatori!", "." },
  ["0ba8503d292d0349"] = { "Quando si è vissuto a lungo quanto me, diventa facile dimenticarsi dell'amore per anni. È sempre bello che qualcuno te lo ricordi.", "." },
  ["0bb34fb1bab2eacf"] = { "%s prova ad aprire il ⟦Maury's Clubbed Foot=Piede Equino di Maury⟧...", "." },
  ["0bb55601c5ae0151"] = { "|cffffff00La Torre Passo Nord è stata conquistata dall'⟦Alliance=Alleanza⟧!|r", "." },
  ["0bc5ad9ac7082151"] = { "Uau!", "." },
  ["0bc5ada7c708215e"] = { "Uau.", "." },
  ["0bcf6c8c4bd2f4a5"] = { "{name}, le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ vanno annientate! Sei <pronto/pronta> per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧?", "." },
  ["0bdbb1f120e1170b"] = { "Ratti dappertutto. Dovunque guardi vedo ratti. Sempre a fissarmi con quei loro occhietti. Gliela farò vedere io. Gliela farò vedere a tutti!", "." },
  ["0be93d3f5a3ce59d"] = { "Mostrami solo la strada, Franclorn.", "." },
  ["0bf1eadc9da37c99"] = { "Esatto!", "." },
  ["0bf6cd82130c69b9"] = { "Ingegnere? Che cosa diamine è, per Skywall?\r\n\nOra che me lo dici... credo di aver sentito quell'ubriacone di Sirrocas, alla locanda, parlare di una specie di spirito della foresta che diceva di aver incontrato e che si faceva chiamare «ingegnere».\r\n\nEra la prima volta che sentivo parlare di una cosa simile.\r\n\nMi pare abbia detto che questo spirito in particolare si trova da qualche parte nella Shadowgale Forest, ma non posso consigliarti di andare in quel posto maledetto!", "." },
  ["0bfa2ecee646b77f"] = { "Se intendi liberare Myzrael, te ne pentirai!", "." },
  ["0bfae3266a9e736d"] = { "Avanti!", "." },
  ["0bfcf142ebf9760a"] = { "Intrusi! Altre pedine dell'⟦Argent Dawn=Alba d'Argento⟧, senza dubbio. Già una di loro è tra i miei prigionieri. Ritiratevi dal mio dominio prima che venga giustiziata!", "." },
  ["0bff3656b4d68b1f"] = { "Vuoi diventare erborista, eh? Allora dovresti far visita a ⟦Firodren Mooncaller=Firodren Vocaluna⟧ nei Giardini del Tempio. Potrebbe avere qualche trucco del mestiere da insegnarti.", "." },
})
